const m=(a,n)=>((a%n)+n)%n;
function mk(X0,X1,Z0,Z1,s){const c=[];
for(let x=X0+s;x<=X1-s;x++)c.push([x,Z0]);
for(let k=0;k<s;k++){c.push([X1-s+k,Z0+1+k]);c.push([X1-s+k+1,Z0+1+k]);}
for(let z=Z0+s+1;z<=Z1-s-1;z++)c.push([X1,z]);
for(let k=0;k<s;k++){c.push([X1-k,Z1-s+k]);c.push([X1-k-1,Z1-s+k]);}
for(let x=X1-s;x>=X0+s;x--)c.push([x,Z1]);
for(let k=0;k<s;k++){c.push([X0+s-k,Z1-1-k]);c.push([X0+s-1-k,Z1-1-k]);}
for(let z=Z1-s-1;z>=Z0+s+1;z--)c.push([X0,z]);
for(let k=0;k<s;k++){c.push([X0+k,Z0+s-k]);c.push([X0+k+1,Z0+s-k]);}
return c;}
